uetooth so I do not key in figures manually.","signedOff":true},{"id":"us-2","story":"As a QC inspector, I want density automatically calculated from volume dimensions and verified against formula thresholds.","signedOff":true},{"id":"us-3","story":"As a warehouse clerk, I want a waterproof QR label generated immediately upon passing verification.","signedOff":true}],"requesterSignedOff":true,"requesterSignedOffBy":"Carlos Reyes","requesterSignedOffAt":"2026-10-16","analystSignedOff":true,"analystSignedOffBy":"Bea Gonzales","analystSignedOffAt":"2026-10-17"},"design":{"skippedForLighterWorkflow":false,"architectureType":"Cloudflare Serverless Edge + SQLite/D1 + LocalStorage PWA fallback","databaseStructureNotes":"Tables: foam_blocks, density_thresholds, scan_logs, calibration_events","figmaMockupUrl":"https://figma.com/design/uratex-scanner-ui","securityChecklistPassed":true,"sapIntegrationRequired":true,"designApproved":true,"designApprovedBy":"Jenor Ricafort","designApprovedAt":"2026-10-19"},"development":{"repositoryBranch":"feature/urx-0087-foam-scanner","assignedDevelopers":["Alex Dimaculangan"],"sprintName":"Sprint 24 - Plant Automation","percentComplete":68,"gitPullRequests":"PR #142 (Merged), PR #149 (In Review)","blockers":"Awaiting 2nd Bluetooth scale unit from Valenzuela calibration lab."},"testing":{"testCases":[{"id":"tc-1","code":"TC-01","title":"Bluetooth weight parsing accuracy ±0.05kg","expectedResult":"Weight auto-populates within 400ms","status":"Pass","testedBy":"Bea Gonzales","testDate":"2026-11-04"},{"id":"tc-2","code":"TC-02","title":"Density calculation formula compliance","expectedResult":"Calculates kg/m3 matching ASTM D3574 standard","status":"Pass","testedBy":"Bea Gonzales","testDate":"2026-11-05"},{"id":"tc-3","code":"TC-03","title":"Offline caching during WiFi dead spots","expectedResult":"Stores up to 500 scans offline and auto-syncs on reconnect","status":"Pending"}],"bugs":[{"id":"bug-1","title":"Zebra printer cut command timing issue on continuous roll","severity":"Minor","status":"Fixed","reportedBy":"Bea Gonzales","assignedTo":"Alex Dimaculangan","dateReported":"2026-11-03"}],"uatSignedOff":false},"documentation":{"completed":false,"systemDocVersion":"v0.7-beta"},"implementation":{"environment":"Staging","databaseMigrationDone":true,"securityAuditCleared":true,"goLiveNotificationSent":false},"training":{"sessions":[{"id":"trn-1","sessionTitle":"Conveyor Shift A & B Operator Hands-on Scanner Training","scheduledDate":"2026-12-05","targetDepartment":"Foam Plant","trainer":"Alex Dimaculangan","attendeesCount":22,"status":"Scheduled"}],"materialsUploaded":false},"evaluation":{"rating":0,"surveyFeedback":"","hoursSavedPerWeek":0,"roiSummary":"","lessonsLearned":""},"maintenance":{"systemHealth":"Optimal","openSupportTickets":0,"lastHealthCheck":"2026-11-08","slaCompliancePercentage":100,"uptimePercentage":99.9}}', 24, 0, 68, 1, 1, 1, 0);
