ith IoT pneumatic valve controller to authorize silo unloading only upon passing test","signedOff":true}],"requesterSignedOff":true,"analystSignedOff":true},"design":{"skippedForLighterWorkflow":false,"architectureType":"Cloudflare Worker microservice + IoT Webhook bridge","securityChecklistPassed":true,"sapIntegrationRequired":true,"designApproved":true,"designApprovedBy":"Jenor Ricafort","designApprovedAt":"2026-09-02"},"development":{"assignedDevelopers":["Alex Dimaculangan"],"percentComplete":100},"testing":{"testCases":[{"id":"tc-71","code":"TC-01","title":"Viscosity tolerance limit enforcement (tolerance ±15 cps)","expectedResult":"Flags warning on out-of-spec batches","status":"Pass","testedBy":"Bea Gonzales"}],"bugs":[],"uatSignedOff":true,"uatSignedOffBy":"Carlos Reyes","uatSignedOffAt":"2026-10-28"},"documentation":{"completed":true,"systemDocVersion":"v1.0.0","userManualUrl":"https://uratex.sharepoint.com/mis/manuals/Chemical-QC-SOP.pdf"},"implementation":{"environment":"Staging","databaseMigrationDone":true,"securityAuditCleared":true,"goLiveNotificationSent":false},"training":{"sessions":[{"id":"trn-71","sessionTitle":"QA Chemist Silo Unloading App Certification","scheduledDate":"2026-11-02","targetDepartment":"Quality Assurance","trainer":"Bea Gonzales","attendeesCount":8,"status":"Completed"}],"materialsUploaded":true},"evaluation":{"rating":0,"surveyFeedback":"","hoursSavedPerWeek":0,"roiSummary":"","lessonsLearned":""},"maintenance":{"systemHealth":"Optimal","openSupportTickets":0,"lastHealthCheck":"2026-11-08","slaCompliancePercentage":100,"uptimePercentage":100}}', 26, 0, 100, 1, 1, 1, 1);

