-- 6. Initial Daily Analytics Snapshot from Seed Data
INSERT OR REPLACE INTO analytics_daily_snapshots (snapshot_date, total_requests, in_dev_requests, in_testing_requests, in_production_requests, total_tasks, completed_tasks, total_effort_days, total_hours_saved_weekly, gate_compliance_pct, active_users_count, updated_at)
SELECT date('now'),
  (SELECT COUNT(*) FROM requests),
  (SELECT COUNT(*) FROM requests WHERE current_sdlc_stage = 5),
  (SELECT COUNT(*) FROM requests WHERE current_sdlc_stage = 6),
  (SELECT COUNT(*) FROM requests WHERE current_sdlc_stage >= 8),
  (SELECT COUNT(*) FROM tasks),
  (SELECT COUNT(*) FROM tasks WHERE status = 'Done'),
  (SELECT COALESCE(SUM(effort_estimate_days), 0) FROM requests),
  (SELECT COALESCE(SUM(hours_saved_per_week), 0) FROM requests),
  100.0,
  (SELECT COUNT(*) FROM users WHERE is_active = 1),
  datetime('now');
